interface SendLogOptions {
    /** 日志内容 */
    content: string;
    /** 日志级别，默认 'info' */
    level?: 'info' | 'warn' | 'error';
    /** 额外信息 */
    extra?: Record<string, string>;
}
interface SendEventOptions {
    /** 事件名称 */
    name: string;
    /** 数值指标 */
    metrics?: Record<string, number>;
    /** 分类维度 */
    categories?: Record<string, string>;
}
type SlardarCallable = (method: string, ...args: unknown[]) => void;
declare global {
    interface Window {
        KSlardarWeb?: SlardarCallable;
    }
}

declare const slardar: {
    sendLog(options: SendLogOptions): void;
    sendEvent(options: SendEventOptions): void;
    captureException(error: unknown, extra?: Record<string, string>): void;
};

export { type SendEventOptions, type SendLogOptions, slardar };
